package week10;

import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Provided - students do not edit this file.
 * Races linear, quadratic and bucket on each of the three datasets and draws it live.
 * Within a dataset the three strategies run at the same time on separate threads.
 * Top chart: keys inserted vs time.   Bottom chart: cost of each insert (collisions per insert) as the table fills.
 */
public class HashRaceVisualizer {

    private interface Strategy {
        long[] run(long[] keys, int tableSize, ProgressListener p);
    }

    private static final String[] STRATEGY_NAMES = {"Linear probing", "Quadratic probing", "Buckets"};
    private static final Color[] COLORS = {
        new Color(220, 50, 47), new Color(38, 139, 210), new Color(42, 161, 80)
    };
    private static final Strategy[] STRATEGIES = {
        HashRace::linear, HashRace::quadratic, HashRace::bucket
    };

    /** One line on one chart. Written by a worker thread, read by the Swing thread. */
    private static class Series {
        final List<long[]> points = new ArrayList<>(); // {elapsedNanos, inserted, collisions}
        volatile long finishNanos = -1;
        volatile String status = "waiting";

        synchronized void add(long nanos, long inserted, long coll) {
            points.add(new long[]{nanos, inserted, coll});
        }

        synchronized List<long[]> snapshot() {
            return new ArrayList<>(points);
        }
    }

    private static class Column extends JPanel {
        final String title;
        Column[] all;
        int n = Datasets.DEFAULT_N;
        volatile long startNanos;
        Series[] series = {new Series(), new Series(), new Series()};

        Column(String title) {
            this.title = title;
            setBackground(Color.WHITE);
            setBorder(BorderFactory.createLineBorder(Color.LIGHT_GRAY));
        }

        void reset(int n) {
            this.n = n;
            series = new Series[]{new Series(), new Series(), new Series()};
            repaint();
        }

        private void axes(Graphics2D g, int left, int top, int pw, int ph, String xLabel, String yLabel) {
            g.setColor(new Color(235, 235, 235));
            for (int i = 1; i < 4; i++) {
                g.drawLine(left, top + ph * i / 4, left + pw, top + ph * i / 4);
            }
            g.setColor(Color.GRAY);
            g.drawRect(left, top, pw, ph);
            g.drawString(yLabel, left, top - 5);
            g.drawString(xLabel, left + pw - g.getFontMetrics().stringWidth(xLabel), top + ph + 28);
        }

        @Override
        protected void paintComponent(Graphics g0) {
            super.paintComponent(g0);
            Graphics2D g = (Graphics2D) g0;
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            Series[] ser = series;
            int w = getWidth(), h = getHeight();
            int left = 62, right = 15;
            int pw = w - left - right;
            int plotH = (h - 390) / 2;
            int top1 = 50, top2 = top1 + plotH + 55;

            g.setFont(getFont().deriveFont(Font.BOLD, 15f));
            g.setColor(Color.BLACK);
            g.drawString(title, left, 22);
            g.setFont(getFont().deriveFont(11f));

            // Every column shares the same scales, so the three datasets can be compared directly.
            List<List<long[]>> pts = new ArrayList<>();
            for (Series s : ser) pts.add(s.snapshot());
            long maxNanos = 1_000_000;
            double maxCost = 1;
            for (Column c : all) {
                for (Series s : c.series) {
                    long prevI = 0, prevC = 0;
                    for (long[] q : s.snapshot()) {
                        maxNanos = Math.max(maxNanos, q[0]);
                        if (q[1] > prevI) maxCost = Math.max(maxCost, (double) (q[2] - prevC) / (q[1] - prevI));
                        prevI = q[1];
                        prevC = q[2];
                    }
                }
            }
            double maxMs = maxNanos / 1e6 * 1.05;
            maxCost *= 1.05;

            // chart 1: inserted vs time
            axes(g, left, top1, pw, plotH, "time (ms)", "keys inserted");
            for (int i = 0; i <= 4; i++) {
                g.setColor(Color.GRAY);
                g.drawString(String.format("%,d", (long) n * i / 4), 4, top1 + plotH - plotH * i / 4 + 4);
                g.drawString(String.format("%.0f", maxMs * i / 4), left + pw * i / 4 - 8, top1 + plotH + 14);
            }
            // chart 2: cost per insert vs how full the table is
            axes(g, left, top2, pw, plotH, "keys inserted so far", "collisions PER insert (cost of one insert)");
            for (int i = 0; i <= 4; i++) {
                g.setColor(Color.GRAY);
                g.drawString(String.format("%,.0f", maxCost * i / 4), 4, top2 + plotH - plotH * i / 4 + 4);
                g.drawString(String.format("%,d", (long) n * i / 4), left + pw * i / 4 - 12, top2 + plotH + 14);
            }

            g.setStroke(new BasicStroke(2.5f));
            for (int i = 0; i < ser.length; i++) {
                g.setColor(COLORS[i]);
                int px = left, py = top1 + plotH, cx = left, cy = top2 + plotH;
                long prevI = 0, prevC = 0;
                for (long[] q : pts.get(i)) {
                    int x = left + (int) (pw * (q[0] / 1e6) / maxMs);
                    int y = top1 + plotH - (int) ((double) plotH * q[1] / n);
                    g.drawLine(px, py, x, y);
                    px = x;
                    py = y;
                    if (q[1] > prevI) {
                        double cost = (double) (q[2] - prevC) / (q[1] - prevI);
                        int x2 = left + (int) ((double) pw * q[1] / n);
                        int y2 = top2 + plotH - (int) (plotH * cost / maxCost);
                        g.drawLine(cx, cy, x2, y2);
                        cx = x2;
                        cy = y2;
                    }
                    prevI = q[1];
                    prevC = q[2];
                }
            }

            // legend + results
            int ly = top2 + plotH + 48;
            g.setFont(getFont().deriveFont(12f));
            boolean allDone = true;
            for (int i = 0; i < ser.length; i++) {
                Series s = ser[i];
                List<long[]> p = pts.get(i);
                long coll = p.isEmpty() ? 0 : p.get(p.size() - 1)[2];
                String time;
                if (s.finishNanos >= 0) {
                    time = String.format("DONE in %,.1f ms", s.finishNanos / 1e6);
                } else {
                    allDone = false;
                    time = s.status.equals("running")
                            ? String.format("running... %,.1f s", (System.nanoTime() - startNanos) / 1e9) : s.status;
                }
                g.setColor(COLORS[i]);
                g.fillRect(left, ly + i * 18 - 10, 12, 12);
                g.setColor(Color.BLACK);
                g.drawString(String.format("%s: %,d collisions - %s", STRATEGY_NAMES[i], coll, time), left + 18, ly + i * 18);
            }
            if (allDone && ser[2].finishNanos >= 0) {
                g.setFont(getFont().deriveFont(Font.BOLD, 12f));
                g.setColor(new Color(90, 30, 140));
                double b = Math.max(ser[2].finishNanos, 1_000);
                g.drawString(String.format("Linear took %,.0fx as long as buckets", ser[0].finishNanos / b), left, ly + 58);
                g.drawString(String.format("Quadratic took %,.0fx as long as buckets", ser[1].finishNanos / b), left, ly + 76);
            }

                            // memory: estimated from the data structure (64-bit JVM, compressed refs), not measured
                            int my = ly + 100;
                            int ts = Datasets.tableSize(n);
                            double maxMem = Math.max(memory(0, ts, n), memory(2, ts, n));
                            g.setFont(getFont().deriveFont(Font.BOLD, 12f));
                            g.setColor(Color.BLACK);
                            g.drawString("Estimated memory used", left, my);
                            g.setFont(getFont().deriveFont(11f));
                            for (int i = 0; i < ser.length; i++) {
                                List<long[]> p = pts.get(i);
                                long ins = p.isEmpty() ? 0 : p.get(p.size() - 1)[1];
                                double mem = ser[i].status.equals("waiting") ? 0 : memory(i, ts, ins);
                                int barW = (int) ((pw - 130) * mem / maxMem);
                                int by = my + 10 + i * 22;
                                g.setColor(COLORS[i]);
                                g.fillRect(left, by, barW, 14);
                                g.setColor(Color.BLACK);
                                g.drawString(String.format("%.2f MB", mem / 1e6), left + barW + 6, by + 12);
                            }
                            g.setColor(Color.GRAY);
                            g.drawString("Open addressing: whole table allocated up front. Buckets: small table + 1 node per key.", left, my + 84);
                        }

                        /** Bytes: long[] = 8 per slot, reference array = 4 per slot, Node = 24 (header 12 + long 8 + ref 4). */
                        private static double memory(int strategy, int tableSize, long inserted) {
                            if (strategy < 2) return 16 + 8.0 * tableSize;
                            return 16 + 4.0 * tableSize + 24.0 * inserted;
                        }
                    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(HashRaceVisualizer::buildUi);
    }

    private static void buildUi() {
        JFrame frame = new JFrame("Week 10 - Hash Collision Race");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        Column[] cols = new Column[Datasets.NAMES.length];
        JPanel grid = new JPanel(new GridLayout(1, cols.length, 8, 8));
        for (int i = 0; i < cols.length; i++) {
            cols[i] = new Column(Datasets.NAMES[i]);
            grid.add(cols[i]);
        }

        JButton start = new JButton("Start race");
        Integer[] sizes = new Integer[Datasets.SIZES.length];
        for (int i = 0; i < sizes.length; i++) sizes[i] = Datasets.SIZES[i];
        JComboBox<Integer> sizeBox = new JComboBox<>(sizes);
        sizeBox.setSelectedItem(Datasets.DEFAULT_N);
        JLabel status = new JLabel("Pick a number of keys and press Start. All charts share the same scales so you can compare them.");
        JPanel bar = new JPanel(new FlowLayout(FlowLayout.LEFT));
        bar.add(start);
        bar.add(new JLabel("keys per dataset:"));
        bar.add(sizeBox);
        bar.add(status);

        for (Column c : cols) c.all = cols;
        frame.add(bar, BorderLayout.NORTH);
        frame.add(grid, BorderLayout.CENTER);
        Rectangle screen = GraphicsEnvironment.getLocalGraphicsEnvironment().getMaximumWindowBounds();
        frame.setBounds(screen);

        new Timer(40, e -> grid.repaint()).start();

        start.addActionListener(e -> {
            int n = (Integer) sizeBox.getSelectedItem();
            start.setEnabled(false);
            sizeBox.setEnabled(false);
            for (Column c : cols) c.reset(n);
            Thread t = new Thread(() -> {
                for (int d = 0; d < cols.length; d++) {
                    int which = d;
                    SwingUtilities.invokeLater(() -> status.setText("Running dataset " + Datasets.NAMES[which] + " ..."));
                    runDataset(which, n, cols[which]);
                }
                SwingUtilities.invokeLater(() -> {
                    status.setText("Finished. Compare the bottom charts: whose cost per insert stays flat? Try a bigger size.");
                    start.setEnabled(true);
                    sizeBox.setEnabled(true);
                });
            }, "race-controller");
            t.setDaemon(true);
            t.start();
        });

        frame.setVisible(true);
    }

    private static void runDataset(int which, int n, Column col) {
        long[] keys = Datasets.get(which, n);
        int tableSize = Datasets.tableSize(n);
        Thread[] workers = new Thread[STRATEGIES.length];
        long start = System.nanoTime();
        col.startNanos = start;
        for (int i = 0; i < STRATEGIES.length; i++) {
            Series s = col.series[i];
            Strategy strategy = STRATEGIES[i];
            s.status = "running";
            workers[i] = new Thread(() -> {
                try {
                    // each strategy gets its own copy so threads can't interfere with each other
                    long[] result = strategy.run(keys.clone(), tableSize,
                            (ins, coll) -> s.add(System.nanoTime() - start, ins, coll));
                    if (result == null || result.length != 2) {
                        s.status = "not implemented (return {inserted, collisions})";
                    } else {
                        s.add(System.nanoTime() - start, result[0], result[1]);
                        s.finishNanos = System.nanoTime() - start;
                    }
                } catch (Throwable ex) {
                    s.status = "error: " + ex;
                }
            }, STRATEGY_NAMES[i]);
            workers[i].setDaemon(true);
        }
        for (Thread w : workers) w.start();
        for (Thread w : workers) {
            try {
                w.join();
            } catch (InterruptedException ignored) {
                Thread.currentThread().interrupt();
            }
        }
    }
}
